examples.code:
// Excerpt from ie4_ev_sub_std.nut: evID/evType/npcHdl are set earlier by
// Initialize()/SetupParam() from the NPC that triggered this event.
evID <- 0;
evType <- 0;
npcHdl <- 0;

// Dispatch to the right event runner depending on the NPC's event type
if (evType == 4)
{
	CallKiznaxEvent(evID, npcHdl);
}
else if (evType == 5)
{
	CallShopEvent(evID, npcHdl);
}
else if (evType == 9)
{
	CallMasterAvatar(evID, npcHdl);
}
else
{
	CallEvent(evID);
}
